insert into public.events (title,date,image,location,description,slug,year,sort_order,published) values ('Social and Emotional Development in Adolescence','December 2022','https://nfvdtfhsxkoipcwtqvcf.supabase.co/storage/v1/object/public/content-images/events-20222023-1.jpg','Renton Highlands Library','A discussion was held at Renton Highlands Library on the topic of adolescent social and emotional development, focusing on Asian children''s mindset and the diversity and cultural policies in Washington State schools. Khulan shared valuable insights, and parents asked many questions about effective communication strategies with their children. Topics included sleepovers at friends'' houses and helping children understand cultural differences during their teenage years.','social-and-emotional-development-in-adolescence-2022-11',2022,0,true) on conflict (slug) do nothing;
insert into public.events (title,image,date,location,description,slug,year,sort_order,published) values ('Seattle''s First Asian Communities & History Tour','https://nfvdtfhsxkoipcwtqvcf.supabase.co/storage/v1/object/public/content-images/events-20222023-2.jpg','February 5, 2023','Panama Hotel Café, downtown Seattle','When people say that there is no discrimination in Seattle, Washington state, it is important to understand the history of the first Asian settlers who brought this opportunity to us. On February 5, 2023, a meeting for 12 children was organized at the Panama Hotel Café in downtown Seattle, where the history of the first Asian settlers in America was shared. During our visit Japanese organized a storytelling event, we participated together, witnessed how 90 years old lady shared her inspirational and thoughtful memory. Thank you Khulan for your dedicated contribution and support.','seattle-s-first-asian-communities-history-tour-2023-12',2023,0,true) on conflict (slug) do nothing;
insert into public.events (title,image,date,description,slug,year,sort_order,published) values ('Microsoft Visit & Mongolian Professionals'' Networking Event','https://nfvdtfhsxkoipcwtqvcf.supabase.co/storage/v1/object/public/content-images/events-20222023-3.jpg','March 17, 2023','A total of 40 participants visited Microsoft, where 9 Mongolian engineers and employees shared their experiences, career paths, and challenges. The session covered career selection, job interviews, internships, and balancing work with hobbies. The children were inspired by Mongolian professionals shaping history in Washington State. Special thanks to our Microsoft mentors!','microsoft-visit-mongolian-professionals-networking-event-2023-13',2023,1,true) on conflict (slug) do nothing;
insert into public.events (title,image,date,description,slug,year,sort_order,published) values ('Blue Origin Tour','https://nfvdtfhsxkoipcwtqvcf.supabase.co/storage/v1/object/public/content-images/events-20222023-4.jpg','May 6, 2023','A group of 5 students and 5 parents visited Blue Origin, the aerospace company founded by Jeff Bezos. Mongolian engineer L. Zolboo hosted the tour, introducing the company''s projects and career opportunities.','blue-origin-tour-2023-14',2023,2,true) on conflict (slug) do nothing;
insert into public.events (title,date,image,description,slug,year,sort_order,published) values ('College Admissions Workshop with Bayarmaa A. from Los Angeles','April 7-8, 2023','https://nfvdtfhsxkoipcwtqvcf.supabase.co/storage/v1/object/public/content-images/events-20222023-5-1.jpg','Over 60 parents and students participated in three different training sessions led by college admissions expert Bayarmaa A. The Seattle team assisted with venue setup, registration, and logistics.','college-admissions-workshop-with-bayarmaa-a-from-los-angeles-2023-15',2023,3,true) on conflict (slug) do nothing;
insert into public.events (title,image,date,description,slug,year,sort_order,published) values ('Amazon Spheres Tour & Career Panel','https://nfvdtfhsxkoipcwtqvcf.supabase.co/storage/v1/object/public/content-images/events-20222023-6.jpg','May 30, 2023','12 participants visited the Amazon Spheres and joined the Asians in Amazon event, where they discussed career choices and professional growth.','amazon-spheres-tour-career-panel-2023-16',2023,4,true) on conflict (slug) do nothing;
insert into public.events (title,date,image,time,description,slug,year,sort_order,published) values ('''Amazon Day for Mongolian Kids''','August 17, 2023','https://nfvdtfhsxkoipcwtqvcf.supabase.co/storage/v1/object/public/content-images/events-20222023-7.jpg','8 AM - 5 PM','88 participants: 66 students, 12 parents, 2 college students, and 2 teachers. Main Program Highlights: iCloud New Version at Amazon (Interactive show for Mongolian students). Future Engineers'' Scholarship (Application process, benefits, and impact). Networking session with Mongolian Amazon employees, engineers, and specialists. Students were divided into high school and middle school groups, engaging in educational and interactive activities.The event was highly effective, and engineers Enerel and Enkhgerel shared their experiences about their university journey, career preparation, and current work.','amazon-day-for-mongolian-kids-2023-17',2023,5,true) on conflict (slug) do nothing;
insert into public.events (title,date,image,location,description,slug,year,sort_order,published) values ('Amazon''s Educational Event Highlights','August 17, 2023','https://nfvdtfhsxkoipcwtqvcf.supabase.co/storage/v1/object/public/content-images/events-20222023-8.jpg','AWS Skills Center, 1915 Terry Ave, Seattle, WA 98101','The Amazon educational training took place in an engaging and interactive format. Participants visited different stations where they learned about new technologies, assembled processors, participated in competitions, and got a hands-on experience with Alexa and other smart home devices. The presenters made complex technological concepts easy to understand, and there were games and presentations from five speakers. All the speakers expressed their gratitude, and the atmosphere was very upbeat and positive.Amazon''s team specifically expressed their appreciation to us. The event was well-organized and well-prepared, with lively and attentive children who understood the tasks and carried them out correctly. Their questions were endless, and the event, which included participants from grades 5-12, was filled with teamwork, warmth, and friendliness. There are many plans for future collaborations, and we heard heartfelt words of encouragement and willingness to continue working together. The success of this event is a testament to the hard work and dedication of many parents and the active participation of the children. Special thanks to Enkhjin, who helped as a teacher at Pinecone, for her dedication. She was there at 8 AM to register and organize the children. Also, thanks to the two teachers from the coding school, the parents, and everyone who donated gifts for the event.','amazon-s-educational-event-highlights-2023-18',2023,6,true) on conflict (slug) do nothing;
insert into public.events (title,date,image,description,details,slug,year,sort_order,published) values ('Coach Erdenechimeg Byambajavs Training on ''Communication, Attitude, Family, and Intergenerational Differences''','January 19-21, 2024','https://nfvdtfhsxkoipcwtqvcf.supabase.co/storage/v1/object/public/content-images/events-2024-1.jpg','Despite the cold weather and snow around Seattle, the training was successfully conducted. A special thanks to the teacher from Washington D.C. who traveled to share her knowledge and experience.','Participants: 12 people','coach-erdenechimeg-byambajavs-training-on-communication-attitude-family-and-intergenerational-differences-2024-1',2024,0,true) on conflict (slug) do nothing;
insert into public.events (title,date,image,location,description,details,slug,year,sort_order,published) values ('Enkhjin''s College Application Workshop','March 3, 2024','https://nfvdtfhsxkoipcwtqvcf.supabase.co/storage/v1/object/public/content-images/events-2024-2.jpg','Kirkland Public Library','Enkhjin Chuluunkhuu shared his experiences applying for college, volunteering, enhancing Common Application activities, and resume writing. The workshop also included guidance on how to improve resumes and create LinkedIn profiles. The students also discussed college applications, scholarships, and essay questions.','Participants: 20 students','enkhjin-s-college-application-workshop-2024-2',2024,1,true) on conflict (slug) do nothing;
insert into public.events (title,image,date,description,slug,year,sort_order,published) values ('Meeting with Dr. M. Saruul-Erdene, a Library Specialist at the U.S. State Department','https://nfvdtfhsxkoipcwtqvcf.supabase.co/storage/v1/object/public/content-images/events-2024-3.jpg','March 15, 2024','Dr. Saruul-Erdene shared insights over coffee about the library''s catalog and the upcoming plans for transitioning into an application system.','meeting-with-dr-m-saruul-erdene-a-library-specialist-at-the-u-s-state-department-2024-3',2024,2,true) on conflict (slug) do nothing;
insert into public.events (title,date,image,description,details,slug,year,sort_order,published) values ('Expedia Company Visit','April 6, 2024','https://nfvdtfhsxkoipcwtqvcf.supabase.co/storage/v1/object/public/content-images/events-2024-7.jpg','The half-day program was successfully organized, and we appreciate Nomingerel for making this happen.','Participants: 5 children, 4 parents','expedia-company-visit-2024-4',2024,3,true) on conflict (slug) do nothing;
insert into public.events (title,image,date,description,slug,year,sort_order,published) values ('QuestBridge Scholarship Info Session','https://nfvdtfhsxkoipcwtqvcf.supabase.co/storage/v1/object/public/content-images/events-2024-4.jpg','May 5, 2024','A 150-minute virtual session on the QuestBridge Scholarship was held, with over 20 parents participating. Munkhnaran, a mother from Denver, shared her experience in preparing her child for the scholarship. She provided valuable insights, strategies, and lessons learned, offering parents practical advice and inspiration for the application process.','questbridge-scholarship-info-session-2024-5',2024,4,true) on conflict (slug) do nothing;
insert into public.events (title,image,date,description,slug,year,sort_order,published) values ('Children''s Day Celebration','https://nfvdtfhsxkoipcwtqvcf.supabase.co/storage/v1/object/public/content-images/events-2024-5-1.jpg','June 1, 2024','As part of our annual Children''s Day tradition, we are launching a new initiative to celebrate and honor high school graduates turning 18 and newborns by giving them special gifts each year. In 2024, we sent congratulatory messages to approximately 55 high school graduates. Los Angeles and Denver graduates received greetings, books, and notebooks from fellow graduates. Washington State graduates were presented with greetings, flowers, and gift cards to mark this milestone.To each of our young Mongolians, we encourage you to cherish and promote the Mongolian language and culture, and always take pride in your Mongolian heritage! 🎉🎓💙','children-s-day-celebration-2024-6',2024,5,true) on conflict (slug) do nothing;
insert into public.events (title,date,image,description,details,slug,year,sort_order,published) values ('College Preparation Strategies, Tactics, and Scholarship Opportunities Workshop','June 8-9, 2024','https://nfvdtfhsxkoipcwtqvcf.supabase.co/storage/v1/object/public/content-images/events-2024-6.jpg','We invited Bolortuya Nasanjargal to conduct a two-day workshop on ''College Preparation Strategies, Tactics, and Scholarship Opportunities.'' This workshop provided a broad yet in-depth understanding of key topics, including:
insert into public.events (title,date,image,description,slug,year,sort_order,published) values ('College Admissions Preparation: Strategies and Tactics Workshop','September 27-28, 2024','https://nfvdtfhsxkoipcwtqvcf.supabase.co/storage/v1/object/public/content-images/events-2024-8.jpg','This event served as a follow-up discussion to the training conducted in June. Guest speaker N. Bolortuya from Los Angeles held 25 one-on-one consultations, providing guidance on course selection, grades, and application strategies to 25 parents/guardians and 28 students. Additionally, 12 participants (students and parents) attended a three-hour group training session.','college-admissions-preparation-strategies-and-tactics-workshop-2024-8',2024,7,true) on conflict (slug) do nothing;
insert into public.events (title,date,image,description,slug,year,sort_order,published) values ('Collaboration with Other Organizations: Mongolian School at ''Eternal Joy'' Church','March to June 2024','https://nfvdtfhsxkoipcwtqvcf.supabase.co/storage/v1/object/public/content-images/events-2024-10.jpg','A Mongolian school operated at the ''Eternal Joy'' church. The children were divided into four levels: Basic Level with Foundation: Knows the alphabet and can read simple words. Basic Level without Foundation: Learning the alphabet from scratch. Intermediate Level – Writing Practice Needed: Can read but needs writing exercises. Intermediate Level – Grammar Needed: Can read but requires grammar lessons.
insert into public.events (title,date,image,description,slug,year,sort_order,published) values ('Celebrating Mongolian Culture and Traditions','Throughout 2024','https://nfvdtfhsxkoipcwtqvcf.supabase.co/storage/v1/object/public/content-images/events-2024-9.jpg','To celebrate the Mongolian Lunar New Year (Tsagaan Sar) and show respect to the oldest residents living in Washington state, we donated 30 copies of the book ''Tsagaan Sar ba Arvan Noyor Jil'' (White Moon and the Twelve Years). This book serves as a reminder of our traditions. Additionally, we participated in the daily activities of the Mongolian Community Association, contributing to the organization and celebration of various events.
insert into public.events (slug,title,date,time,location,image,description,details,year,published,sort_order) values ('naadam-festival-2024','Naadam Festival 2024','July 11-13, 2024','10:00 AM - 6:00 PM','Seattle Center','/placeholder.svg','Experience the excitement of Mongolia''s largest cultural festival featuring traditional sports, music, and dance performances.','The Naadam Festival, known as ''The Three Games of Men'', celebrates Mongolian culture through competitions in wrestling, horse racing, and archery. Join us for this vibrant celebration of Mongolian heritage and enjoy traditional food, music, and crafts alongside the exciting competitions.',2024,false,101) on conflict (slug) do nothing;
insert into public.events (slug,title,date,time,location,image,description,details,year,published,sort_order) values ('lunar-new-year-2024','Lunar New Year Celebration','February 10, 2024','11:00 AM - 4:00 PM','MCCCW Center','/placeholder.svg','Welcome the Year of the Dragon with traditional ceremonies, performances, and festive activities.','Celebrate the Lunar New Year with us as we welcome the Year of the Dragon. Enjoy traditional Mongolian and Asian performances, participate in cultural workshops, and savor delicious festive cuisine. This family-friendly event is a perfect way to experience the rich traditions of Lunar New Year celebrations.',2024,false,102) on conflict (slug) do nothing;
insert into public.events (slug,title,date,time,location,image,description,details,year,published,sort_order) values ('music-workshop-2024','Traditional Music Workshop','March 15, 2024','2:00 PM - 5:00 PM','MCCCW Music Hall','/placeholder.svg','Learn about Mongolian musical instruments and throat singing in this interactive workshop.','Immerse yourself in the world of traditional Mongolian music with our expert instructors. This hands-on workshop will introduce you to various Mongolian instruments such as the morin khuur (horsehead fiddle) and the yatga (zither). You''ll also get a chance to learn about the unique art of Mongolian throat singing. Suitable for all levels of musical experience.',2024,false,103) on conflict (slug) do nothing;
insert into public.events (slug,title,date,time,location,image,description,details,year,published,sort_order) values ('summer-festival-2023','Mongolian Summer Festival 2023','August 5-6, 2023','11:00 AM - 7:00 PM','Magnuson Park','/placeholder.svg','A celebration of Mongolian culture with food, music, and traditional games.','Join us for a weekend of Mongolian culture at our annual Summer Festival. Enjoy authentic Mongolian cuisine, watch traditional dance and music performances, and participate in fun cultural games and activities. This family-friendly event is a great opportunity to experience the warmth and vibrancy of Mongolian hospitality.',2023,false,104) on conflict (slug) do nothing;
insert into public.events (slug,title,date,time,location,image,description,details,year,published,sort_order) values ('art-exhibition-2023','Contemporary Mongolian Art Exhibition','May 20-June 10, 2023','Gallery Hours: 10:00 AM - 5:00 PM','MCCCW Gallery','/placeholder.svg','Explored modern interpretations of traditional Mongolian art forms by local artists.','This exhibition showcases the work of contemporary Mongolian-American artists, blending traditional Mongolian artistic techniques with modern themes and mediums. From paintings and sculptures to multimedia installations, this exhibition offers a unique perspective on the evolving Mongolian-American cultural identity.',2023,false,105) on conflict (slug) do nothing;
insert into public.events (slug,title,date,time,location,image,description,details,year,published,sort_order) values ('winter-solstice-2022','Winter Solstice Celebration 2022','December 21, 2022','6:00 PM - 9:00 PM','MCCCW Center','/placeholder.svg','Celebrated the winter solstice with traditional Mongolian customs and warm fellowship.','Join us for a magical evening as we celebrate the winter solstice in true Mongolian style. Experience traditional rituals, enjoy warming foods, and participate in cultural activities that honor this important time of year. This event is a wonderful opportunity to connect with the community and learn about Mongolian winter traditions.',2022,false,106) on conflict (slug) do nothing;
insert into public.programs (title,image,description,details,slug,published,sort_order) values ('"Mongolian identity-Mongolian talent" (MIT-phase 1)','https://nfvdtfhsxkoipcwtqvcf.supabase.co/storage/v1/object/public/content-images/programImages-mit.jpg','On December 14, 2024, the first five children out of the 13 participants in the "Mongolian identity-Mongolian talent" project received their scholarships, learned about project writing methodology, and had a wonderful evening with our first donor, Mr. Davaa.','Project Funders: Sponsors from the U.S. West Coast and Mongolia, including individuals with Ph.D., Master''s, and Bachelor''s degrees, researchers, teachers, coaches, and businesspeople we greatly respect. All are sources of pride.
insert into public.programs (title,image,description,details,slug,published,sort_order) values ('"Mongolian Identity - Mongolian Talent" Cultural Event','https://nfvdtfhsxkoipcwtqvcf.supabase.co/storage/v1/object/public/content-images/programImages-ankhaa.jpg','11th-grade student M. Ankhbayar organized a film day featuring the movie Blue Spot People on January 26, 2025, from 1:00 PM to 4:00 PM. The three-hour event included watching the film, writing reviews and critiques, engaging in discussion exercises, a quiz based on the movie''s storyline, karaoke for young children, and interactive competitions to test skills and creativity.','Around 40 children and parents participated. The film analysis worksheet was designed to suit different age groups, including elementary, middle, and high school students, ensuring an age-appropriate learning approach.
insert into public.programs (title,image,description,details,slug,published,sort_order) values ('"Legacy of the Yuan Dynasty in World History" Cultural Event','https://nfvdtfhsxkoipcwtqvcf.supabase.co/storage/v1/object/public/content-images/programImages-tumurkhuu.jpg','Henry Jackson High School sophomore Tumurkhuu Amarbold organized a cultural event titled Legacy of the Yuan Dynasty in World History. Participants immersed themselves in the history of the Yuan Empire, traveling back in time to the era of Genghis Khan, his descendants, and Kublai Khan. Historical records highlight that these great 13th-century rulers were not only conquerors but also pioneers in civilization, urban planning, postal communication, trade, arts, and sciences.','Tumurkhuu was awarded the U.S. President''s Community Service Award Silver Medal and a certificate by President Joe Biden. He dedicated 188 hours to this project and three summer camp sessions, demonstrating his dedication, kindness, and responsibility in organizing games and competitions.
insert into public.programs (title,image,description,details,slug,published,sort_order) values ('"Mongolian Identity - Mongolian Talent" Project Scholarship Recipient Hosted event on December 22, 2024','https://nfvdtfhsxkoipcwtqvcf.supabase.co/storage/v1/object/public/content-images/programImages-telmen.jpg','T. Telmen, a recipient of the $200 scholarship from the Mongolian Identity - Mongolian Talent project, successfully hosted a two-hour event introducing famous book "The Story of Discovering the World" by Tudev Lodongiin. The event was a dynamic mix of education, games, and interactive learning, with 55–56 participants engaging in various activities.','Despite his busy schedule as a high school senior student preparing for college application and spring graduation, Telmen successfully completed his project. Special thanks to Maral for assisting his older brother.
insert into public.programs (title,image,description,details,slug,published,sort_order) values ('Seattle Kids Discover the World Through Books','https://nfvdtfhsxkoipcwtqvcf.supabase.co/storage/v1/object/public/content-images/programImages-nomtelmen.jpg','"Mom, can I have a toy?" I once asked. "Go to the river! Your toys are waiting there," she replied. Upon arriving at the river, I found children hunched over the stones, searching for something. "There''s nothing you can''t find among these river stones," a girl said. "Chests, bowls, robes, sweets, horses, camels—everything is here."','Thus began a young boy''s journey of discovery—through sound, drawing, wind, schoolbags, discipline, wrestling, Lenin, theater, inventions, sports, masks, lies, horses, traps, marmots, and even mythical rock monsters. From early childhood to becoming a student at a town school, this story captures the wonder of learning and exploration.
insert into public.programs (title,image,description,details,slug,published,sort_order) values ('Mongolian Ger Presentation at Washington State Naadam Festival','https://nfvdtfhsxkoipcwtqvcf.supabase.co/storage/v1/object/public/content-images/programImages-binderiyaKhaliun.jpg','Binderya bayarsaikhan and Khaliun Batbayar, who are implementing the "Mongolian Identity - Mongolian Talent" project, presented their project on Saturday, August 10, 2020, from 2-3 PM. As part of their presentation, they set up a Mongolian ger (yurt) and held discussions about Mongolian traditions and culture.','These dedicated students received a $200 each scholarship in December 2023. During the Washington State Naadam Festival, they showcased a traditional Mongolian ger, allowing children and the public to explore and learn about it. The ger was set up on the lawn in front of UW Madrona Hall.
