insert into public.reviews (id,name,rating,comment,approved) values ('00000000-0000-4000-8000-000000000022','Bolortuya',5,'Good morning, Seattle moms! I have safely arrived back home. Thank you for inviting me and making me feel so welcome. Although I am back, I still cannot forget the warm and wonderful two days spent in Seattle.',true) on conflict (id) do nothing;
